<?php
ini_set('display_errors','0');error_reporting(E_ALL);require __DIR__.'/../lib/Db.php';require __DIR__.'/../lib/Jwt.php';require __DIR__.'/../lib/XlsxWriter.php';$CFG=require __DIR__.'/../config.php';$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m)){http_response_code(401);exit('Unauthorized');}$p=Jwt::verify(trim($m[1]),$CFG['jwt_secret']);if(!$p){http_response_code(401);exit('Unauthorized');}$u=Db::one("SELECT u.id,r.title role_title,r.is_admin FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND u.is_active=1",[$p['sub']]);$ok=$u&&!empty($u['is_admin'])||($u&&in_array($u['role_title'],['مدیر کل','رییس اداره بازرسی','نیروی اداری ارشد'],true));if(!$ok){http_response_code(403);exit('Forbidden');}
$type=(int)($_GET['type_id']??0);$rows=Db::all("SELECT s.id,s.station_code,s.station_status,s.station_name,s.latitude,s.longitude,s.accuracy_m,s.captured_at,l.code line_code,l.origin,l.destination,t.title sign_type,sg.photo_path,CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,'')) captured_by FROM line_station_signs sg JOIN line_station_locations s ON s.id=sg.station_location_id JOIN station_sign_types t ON t.id=sg.sign_type_id JOIN `lines` l ON l.id=s.line_id LEFT JOIN users u ON u.id=s.captured_by WHERE (?=0 OR t.id=?) ORDER BY s.captured_at DESC",[$type,$type]);$x=new XlsxWriter(['شماره ایستگاه','وضعیت','نام ایستگاه','خط','مبدأ','مقصد','نوع تابلو','Latitude','Longitude','دقت GPS','تاریخ ثبت','ثبت‌کننده','تصویر تابلو','لینک نقشه']);$x->setImageColWidth(12,16);foreach($rows as $r){$n=$x->addRow([$r['station_code']?:'ناموجود',$r['station_status']==='missing'?'غیرفعال/ناموجود':'فعال',$r['station_name']?:'',$r['line_code']?:'',$r['origin']?:'',$r['destination']?:'',$r['sign_type']?:'',$r['latitude'],$r['longitude'],$r['accuracy_m'],$r['captured_at'],$r['captured_by'],'','https://www.google.com/maps?q='.rawurlencode($r['latitude'].','.$r['longitude'])]);$path=__DIR__.$r['photo_path'];if(is_file($path))$x->setImage($n,12,@file_get_contents($path));}$x->output('گزارش_تابلو_ایستگاهها.xlsx','تابلوها');